def load_defaults_configuration(self, silent=False):
    for option, value in utils.get_global_settings().items():
        setattr(self.parameters, option, value)

    # Rewrite variables with env. variables
    destination_pipeline_host = os.getenv('DESTINATION_PIPELINE_HOST', '127.0.0.1')
    source_pipeline_host = os.getenv('SOURCE_PIPELINE_HOST', '127.0.0.1')

    setattr(self.parameters, 'destination_pipeline_host', destination_pipeline_host)
    setattr(self.parameters, 'source_pipeline_host', source_pipeline_host)

    if os.getenv('INTELMQ_IS_DOCKER', None):
        pipeline_host = os.getenv('INTELMQ_PIPELINE_HOST')
        if pipeline_host:
            setattr(self.parameters, 'destination_pipeline_host', pipeline_host)
            setattr(self.parameters, 'source_pipeline_host', pipeline_host)
